func isSafePath(baseDir, userDir string) bool {
	cleanDir := filepath.Clean(userDir)
	if !strings.HasPrefix(cleanDir, "/") {
		cleanDir = "/" + cleanDir
	}
	fullPath := filepath.Join(baseDir, cleanDir)
	return strings.HasPrefix(fullPath, baseDir)
}

